import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { writeFileSync } from 'node:fs';
import { registerHooks } from 'node:module';

const capture = Symbol.for('lunr/private-computer-inventory');
globalThis[capture] = (context) => {
  const browser = context.tools.some((tool) => tool.name === 'browser');
  const stem = `first-request-browser-${browser ? 'on' : 'off'}`;
  const withoutComputer = context.tools.filter((tool) => tool.name !== 'computer_load');
  const hash = createHash('sha256').update(JSON.stringify(withoutComputer)).digest('hex');
  assert.equal(hash, browser ? 'c7a60ad06073297d688a4ec1b5c7056ae9ff6df1738123b0d471f20aa0a85bbf' : '3693bff47d556206b75ccf61c3c6de2cd53f81e0a40c441fe6210993972287fa');
  writeFileSync(new URL(`${stem}.tools.json`, import.meta.url), JSON.stringify(context.tools, null, 2));
  writeFileSync(new URL(`${stem}.prompt.md`, import.meta.url), context.systemPrompt);
};
registerHooks({ load(url, context, nextLoad) {
  const result = nextLoad(url, context);
  if (!url.includes('/node-runtime/benchmark-request-')) return result;
  const source = String(result.source);
  const needle = 'let toolSchemaHash =';
  assert(source.includes(needle));
  return { ...result, source: source.replace(needle, 'globalThis[Symbol.for("lunr/private-computer-inventory")](context); ' + needle) };
} });

