const env = Object.fromEntries(Object.entries(process.env).filter(([key]) => !/^PI_|TOKEN|SECRET|API_KEY|^CUA_|^NODE_OPTIONS$/i.test(key)));
const suites = {
 'coding-agent': ['install-features', 'extensions-discovery', 'suite/regressions/5724-sigterm-signal-exit'],
 ai: ['opencode-catalog', 'openai-completions-tool-choice', 'anthropic-force-adaptive-thinking', 'anthropic-empty-thinking-signature-compat', 'anthropic-adaptive-thinking-models'],
};
for (const [label, root] of [['head', resolve('.')], ['base', resolve('../lunR-pr77-validation-base')]]) {
 const home=join(output,`ci-${label}-home`); mkdirSync(home,{recursive:true});
